from functools import lru_cache

def optimal_sum_diff(nums):
    n = len(nums)
    @lru_cache(None)
    def dp(start, end):
        if end - start < 2:
            return 0
        take_left = nums[start] + 2 * (dp(start + 1, end))
        take_right = nums[end] + 2 * (dp(start, end - 1))
        take_both = nums[start] + nums[end]
        take_slice = 0
        for i in range(start + 1, end):
            take_slice += nums[i]
        return max(take_left, take_right, take_both, take_slice)

    return dp(0, n - 1) - dp(1, n)

# Example inputs
