from math import inf

def optimal_moves(paper_values, turn):
    memo = {}
    def dp(i, j):
        if i > j:
            return 0
        if (i, j) in memo:
            return memo[(i, j)]
        if i == j:
            memo[(i, j)] = paper_values[i]
            return paper_values[i]
        k = min([(a - b) // turn, a, b] for a, b in zip(paper_values, paper_values[i+1:]))
        memo[(i, j)] = k[0] * turn + paper_values[i] * 2 - k[1] * turn
        return memo[(i, j)]
