from bisect import bisect_left

def find_max_candies(N, K, x, D):
    if x < D:
        return -1

    min_p1 = 0
    max_p1 = x - D
    values = []

    for p in list(set(range(x))) + [max_p1 + 1]:
        i = bisect_left(values, p - D)
        if i < len(values) and values[i] > p:
            values.insert(i, p)
        else:
            values.append(p)
            continue
        values = values[:i] + sorted(values[i:])
        if len(values) < K:
            values.pop(0)

    if len(values) < K:
        return -1

    dp = []
    for i in range(1, K + 1):
        if not dp:
            dp.append(values[i - 1])
        else:
            dp.append(values[i - 1] - values[dp[0]])

    if len(dp) != N:
        return -1

    return sum(dp)

