from math import sqrt
from collections import Counter
from functools import reduce
from typing import List

def two_integers(x1: int, x2: int) -> int:
    score = ((x1 - 1) * (x2 - 1)) // 2 + 1
    return score

def events(x: int, K: int, T: int) -> int:
    finders, total = Counter(), 0
    for e in sorted(x.items()):
        val = e[1]
        idx = e[0]
        for player in range(1, T + 1):
            if val >= K:
                if finders[player] <= 0:
                    total += len(finders)
                    total -= two_integers(finders[1], val)
                    del finders[1]
                if val + 1 < K:
                    del finders[player]
                total -= two_integers(val + 1, val)
            if idx == T:
                return total
            val = e[1]
            idx += 1
    return total

def answer(log: List) -> int:
    return log[1]

def max_ends(phases: List[List[int]]) -> int:
    return max(phases[i][1] - phases[i][0] + 1 for i in range(0, len(phases), 2))

def max_toug_of_war(N: int, K: int) -> int:
    return reduce(events, Counter([(i, max_phases) for p1, max_phases in phases]), 0) % (10**14 + 7)
