from math import gcd

def find_period(a, k, mode=0):
    x, y = 1, 0
    for n in range(len(a)):
        x, y = y, (x * k + a[n]) % (gcd(x, k) if mode == 1 else gcd(x, y, k))
        if x == 0:
            break
    return x, n

def game(a, k):
    n = len(a)
    periods = []
    for i in range(1, k):
        x, lin = find_period(a, i)
        y, lout = find_period(a, i+1)
        if lin < lout:
            periods.append(lin + y)
        else:
            periods.append(lin + x)
    if lin < lout:
        periods.append(lin)
    else:
        periods.append(lin - x)
    period = periods.pop()
    res1, res2 = period // lout * 2 * lout, 0
    while period > 0:
        period = period % lout
        if period > 0:
            period -= lout
            res1 += a[lin + period-1]
        else:
            if period == -1:
                start = lin
            for i in range(-1 if not period else period):
                res2 += a[lin + start + i]
            lin, start += 1
    return res1 - res2

