@lru_cache(maxsize=None)
def catalan(n):
    return (1 / math.sqrt(2)) * math.comb(2 * n, n)

@lru_cache(maxsize=None)
def binomial(n, k):
    if n < k :
        k = n - k
    if n < 0 or k < 0 or k > n :
        return 0
    if k == 0 or n == k :
        return 1   
    return binomial(n - 1, k) + binomial(n - 1, k - 1)

@lru_cache(maxsize=None)
def binomial_by_additions(n, k):
    if n < 0 or k < 0 or k > n :
        return 0
    elif k == 0 or n == 0:
        return 1
    elif k == 1:
        return n + 1
    else:
        return binomial_by_additions(n - 1, k - 1)

@lru_cache(maxsize=None)
def factorials(n):
    if n == 0:
        return 1
    return n * factorials(n-1)

def combi(n, k):
    big_fact = factorials(n)
    num_fact = factorials(k) * factorials(n - k)
    return big_fact // num_fact

def cati(n):
    return combi(2 * n, n) // (n + 1)

def helper(n, k):
    ways = 0
    for i in range(k+1):
        ways += cati(n - 2 * i // 2) * cati(i)
        ways %= 100000000000007
    return ways

