import sys

def solve(n, m, edges, positions, q, queries):
    graph = [[] for _ in range(n)]
    for u, v in edges:
        u, v = min(u, v), max(u, v)
        if u != n:
            graph[u].append((v, True))
            graph[v].append((u, False))

    pos_index = {p: i for i, p in enumerate(positions)}
    visited = [False] * n
    for i, (p, c) in enumerate(zip(positions, queries)):
        depth = [0] * n
        level = {i}
        queue = [(i, 0)]
        seen = {i}
        a, b = None, None
        while queue:
            p, h = queue.pop(0)
            if h > depth[p]:
                for node in graph[p]:
                    if (node[0], node[1]) not in seen:
                        queue.append((node[0], h + 1))
                        seen.add((node[0], node[1]))
            elif h == depth[p]:
                if p in level:
                    a = level[p]
                elif b is None:
                    b = level[p]
                else:
                    level[b] = p
                seen.add((p, h + 1))
                level.pop(a)
                if a not in seen and a != b:
                    if a not in level:
                        level[a] = b
                    else:
                        level[a] = p

        def propagate(i):
            p, dir = i
            for node in graph[p]:
                if dir != node[1]:
                    for _ in range(2):
                        propagate(node)
                        node = edge[node[1], node[0]]
            i = (edge[i[0], i[1]], dir or '2') if (3 not in level) else i

        def join(i, j):
            i, j = graph[i], graph[j]
            for l in j:
                l = node[l[1], l[0]]
                for l2 in l:
                    d2, l2 = (0, '2') if (3 in level) else l2
                    l1 = edge[i[0], i[1]]
                    if l1 == (0, d2):
                        join(l1, l2)
                        continue
                    if l1 == (3, d2):
                        join(l2, l1)
                        continue
                    join(i, j)
            return '3'

        root = -1
        result = 0
        while max([depth[h] - level[h] for h in visited]) == 0:
            idx = -1
            for i in visited:
                if idx == -1 and level[i] in max(level.keys(), key=lambda x: sum(abs(p - (x[0][0] + x[0][1] - p)) for p in i)):
                    idx = i
                result += sum([abs(p[1][0] - positions[i][1]) for p in range(pos_index[idx], pos_index[i] + 1)])
            if idx == -1 or root == idx:
                break
            root = propagate(idx) or join(idx, root)
            visited.remove(idx)
            for p in [level[idx], idx]:
                for i in range(len(graph[p])):
                    graph[p][i] = queue[i]

    return result

