def count_swaps(k):
    power_map = {1: 1, 2: 2, 3: 5}
    mod = 10**9 + 7
    if k <= 0:
        return [0] * k
    elif k == 1:
        return [1]
    elif k == 2:
        return [2, 1]
    swaps = [1]
    for i in range(1, k):
        power_next = power_map[i] * (pow(power_map[i]+1, power_map[i]-1, mod) - 1)
        swaps.extend([power_next, power_next])
    return swaps[:k]

