import sys

def count_good_pairs(n, k, tasks):
    num_pairs = 0
    start = 1
    end = 1
    for i in range(1, n):
        if i <= k:
            num_pairs += i ** 2
        else:
            num_pairs += (k + 1) ** 2 - (end - start + 1) ** 2
        while tasks[start] * i <= sum(tasks[start:end]):
            start += 1
        while tasks[end - 1] * i > sum(tasks[start:end]):
            end -= 1
    return num_pairs

