        speeded_backwards = modSpeededFCN(num - 2, fc[num-2], fc[num-2]-1, memo*2+memo)

        new_val = (num * (num - 1) // 2)
        new_val -= speeded_backwards[0] + speeded_forwards[1]
        speeded_list[num+1]=(num, memo)

        speeded_cache[0] = new_val
        speeded_list[num+2].append(new_val)

        return new_val, memo

