def pairs_with_equal_sum(arr):
    unique_elements = sorted(set(arr))
    dp = [0] * len(unique_elements)
    dp[unique_elements[0] * -1] = 1

    for i in range(1, len(arr)):
        for j in range(len(unique_elements)):
            if i % 2 == 0 and unique_elements[j] > arr[i]:
                dp[unique_elements[j]] += dp[unique_elements[j-1]]
            elif i % 2 == 1 and unique_elements[j] < arr[i]:
                dp[unique_elements[j]] += dp[unique_elements[j+1]]

    return sum(dp[unique_elements]) + len(unique_elements)

def count_good_pairs(tasks):
    unique_tasks = sorted(set(tasks))
    total_good_pairs = pairs_with_equal_sum(tasks)
    segment = (len(unique_tasks) + 1) // 2
    for i in range(segment):
        total_good_pairs += len(unique_tasks) - 1 - i
