def find_max_candies(N, K, x, D):
    # If K students are known for sure, check if we can distribute chocolates in a way that all constraints are satisfied
    if K < 2 * x or D > 1 + x:
        return -1

    # If there are only two students, the answer is always correct
    if K == 2:
        return 2 * x - x * 2 * (N - 2) // (x + 1)

    max_chocolates = 0

    # Consider each possible value between 1 and x for each student, starting from 1
    for candies in range(1, x + 1):
        # Check if this limit of chocolates satisfies all conditions
        if K < 2 * candies or D > 1 + x - candies:
            continue
        # Check if for each student, there is at least one enough other student next to them
        if all(candies + i <= x and candies - i >= 1 for i in range(1, x + 1)):
            max_chocolates = max(max_chocolates, 2 * candies)

    return max_chocolates

