        self.visited = defaultdict(int)
        self.path_found = False

    def add_interval(self, interval1: int, interval2: int) -> None:
        self.graph[interval1].append(interval2)
        self.graph[interval2].append(interval1)

    def process_query(self, query_type: int, query_data: int) -> None:
        interval1, interval2 = query_data, query_data + 1
        if query_type == 1:
            if interval2 > len(self.graph) or len(self.graph[interval1]) == 0:
                self.visited[interval1] = 1
            else:
                for neighbour in self.graph[interval1]:
                    self.add_interval(interval1, neighbour)
                    if neighbour == interval2 or self.visited[neighbour]:
                        break
                    self.visited[neighbour] = 1
        else:
            self.path_found = False
            for neighbour in self.graph[interval1]:
                if self.visited[neighbour]:
                    continue
                if neighbour == interval2 or self.visited[neighbour]:
                    break
                self.path_found = True
                if self.visited[neighbour]:
                    break
            print("YES" if self.path_found else "NO")

