import sys
from collections import defaultdict

class IntervalTree:
    def __init__(self, start, end):
        self.start = start
        self.end = end
        self.left = None
        self.right = None

    def insert(self, start, end):
        if start > self.end:
            self.right = IntervalTree(start, end)
        elif start < self.start:
            self.left = IntervalTree(start, end)
        else:
            self.end = max(self.end, end)
        if not self.left and not self.right:
            self.left = IntervalTree(-1, -1)
            self.right = IntervalTree(-1, -1)

    def find_path(self, interval):
        if self.start <= interval[0] < self.end and self.start <= interval[1] < self.end:
            return "YES"
        if self.left and any(self.left.find_path(interval) == "YES" or self.right.find_path(interval) == "YES"):
            return "YES"
        return "NO"

def process_query(query):
    if query.startswith("1"):
        start, end = map(int, query.strip().split())
        tree.insert(start, end)
    if query.startswith("2"):
        interval_id_first, interval_id_second = map(int, query.strip().split())
        return tree.find_path((interval_id_first - 1, interval_id_second - 1))

def main():
    n = int(sys.stdin.readline().strip())
    tree = IntervalTree(-1, -1)
    for _ in range(n):
        query = sys.stdin.readline().strip()
        print(process_query(query))

if __name__ == "__main__":
